/* v28.xx (cw-setname) critic c-31 round 12 (Settings 18 and 72 at 2: "the footer shows only a warning with no setting name"; "the arrows are tiny, about 12px, thin and dim"; "the Display section label repeats the active tab name"). Now: the pane wears the row name at 20px over its help line, the value stays in the row, the stepper arrows are 28px. */
#root #setdetail .sdk{ display:block; font-size:var(--fs-body); font-weight:600; line-height:1.3; }
#root #setdetail .sdv{ display:none; }
#root #setdetail .sdh{ margin-top:var(--sp-1); }
#root #setlist .row > button[id^="go_"]::before, #root #setlist #set_text::before, #root #setlist #set_layout::before, #root #setlist #set_music::before,
#root #setlist #set_auto::before, #root #setlist #set_share::before, #root #setlist .row > button[id^="go_"]::after, #root #setlist #set_text::after, #root #setlist #set_layout::after, #root #setlist #set_music::after,
#root #setlist #set_auto::after, #root #setlist #set_share::after{ font-size:var(--fs-title); color:var(--tx-2); }
#root #setlist .row > button.padfocus::before, #root #setlist .row > button.padfocus::after{ color:var(--acc); }

check:
{v:'VER',what:'the Settings pane names the row, the stepper arrows are 28px and the first section label that repeats the tab is hidden',
 run:function(){
   var bad=[], d, k, a, h, i, bs, fs=null, padWas=document.body.classList.contains('padon');
   __runPrep(); __topClear(); __resetCfg(); __pinDefaults(0); __cleanProfile();
   try{
     document.body.classList.remove('padon');
     openSettings('display');
     if(typeof window.__setDetailSync==='function') window.__setDetailSync();
     d=document.getElementById('setdetail'); k=d&&d.querySelector('.sdk');
     if(!d) bad.push('no detail pane');
     else if(k&&getComputedStyle(k).display==='none') bad.push('the detail pane hides the row name');
     bs=document.querySelectorAll('#setlist .row > button');
     for(i=0;i<bs.length;i++){ a=getComputedStyle(bs[i],'::before'); if(a.content&&a.content!=='none'&&a.content!=='normal'&&bs[i].offsetParent){ fs=parseFloat(a.fontSize); break; } }
     if(fs===null) bad.push('no stepper arrow found');
     else if(fs<27) bad.push('the stepper arrows are '+fs+'px');
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{ try{ var q=document.getElementById('settingsmodal'); if(q) q.classList.remove('on'); }catch(_k){} try{ __topClear(); }catch(_c){} document.body.classList.toggle('padon',padWas); }
   return bad.length?bad.join('; '):null; }},
